'use strict';
let D, selectedCase, caseRequest=0, ledgerPage=0;
async function readData(path){
 if(location.protocol!=='file:'){const r=await fetch(path);if(!r.ok)throw new Error('Evidence response '+r.status);return r.json();}
 if(window.QUASILISK_JSON?.[path])return window.QUASILISK_JSON[path];
 return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=path+'.js';script.onload=()=>{const value=window.QUASILISK_JSON?.[path];script.remove();value===undefined?reject(new Error('Offline evidence asset missing')):resolve(value)};script.onerror=()=>{script.remove();reject(new Error('Missing offline evidence asset: '+path))};document.head.append(script);});
}

const page=document.body.dataset.page;
const pages=[['index','Overview'],['results','Scientific results'],['judging','Judging'],['selector','Selector & strategies'],['runtime','Runtime & budget'],['conversations','Conversations'],['methodology','Evidence & method']];
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(v,d=0)=>Number(v).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const money=(v,d=4)=>'$'+number(v,d);
const pct=(a,b,d=1)=>number(b?100*a/b:0,d)+'%';
const shortModel=m=>({'meta-llama/llama-3.1-8b-instruct':'Llama 3.1 8B','qwen/qwen3.7-flash':'Qwen 3.7 Flash','anthropic/claude-haiku-5.5':'Haiku 5.5','deepseek/deepseek-v4.1-flash-1017':'DeepSeek V4.1 Flash','openai/gpt-6-luna-pro':'Luna Pro'}[m]||m);
const cap=s=>s?String(s)[0].toUpperCase()+String(s).slice(1):'—';
const label=s=>String(s??'—').replaceAll('_',' ');
const colorScore=s=>s===null?'var(--muted)':Number(s)>=90?'var(--violet)':Number(s)>=70?'var(--blue)':Number(s)>25?'var(--amber)':'var(--muted)';
const score=s=>s===null?'—':number(s,Number(s)%1?1:0);
const badge=(s,type='')=>`<span class="badge ${E(type)}">${E(s)}</span>`;
const stat=(title,value,description,cls='')=>`<div class="metric"><div class="label">${E(title)}</div><strong class="${E(cls)}">${E(value)}</strong><p>${description}</p></div>`;
const linkCase=(id,text='Read complete conversation',view='transcript')=>`<a href="conversations.html?case=${encodeURIComponent(id)}&view=${encodeURIComponent(view)}">${E(text)} ↗</a>`;
const caseButton=(id,text='Open evidence',view='transcript')=>`<a class="button small" href="conversations.html?case=${encodeURIComponent(id)}&view=${encodeURIComponent(view)}">${E(text)} ↗</a>`;
const callButton=(id,text='Inspect call')=>`<a class="button small" data-call="${E(id)}" href="runtime.html?call=${encodeURIComponent(id)}">${E(text)} ↗</a>`;
const head=(n,title,intro)=>`<header class="page-head"><div class="eyebrow"><strong>${E(n)}</strong> / VERIFICATION REVIEW · 12 NOV 2026</div><h1>${title}</h1><p class="intro">${intro}</p></header>`;
const section=(k,title,body,note='')=>`<section class="section"><div class="section-head"><div><div class="eyebrow">${k}</div><h2>${title}</h2></div>${note?`<p>${note}</p>`:''}</div>${body}</section>`;
const table=(headers,rows,cls='')=>`<div class="table-wrap"><table class="${E(cls)}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const jsonDetails=(title,value)=>`<details><summary>${E(title)}</summary><pre>${E(JSON.stringify(value,null,2))}</pre></details>`;
const params=()=>new URLSearchParams(location.search);
const byCase=id=>D.observations.find(o=>o.id===id);
const runName=r=>`${cap(r.objective)} · ${shortModel(r.target)}`;
const obsName=o=>`${cap(o.objective)} / ${shortModel(o.target)} / #${o.target_sequence}`;
const bars=(items,max)=>items.map(([name,value,display,color])=>`<div class="bar-row"><span>${E(name)}</span><div class="bar-track" role="img" aria-label="${E(name)}: ${E(display)}"><i style="width:${Math.max(0,Math.min(100,100*value/max))}%;--color:${color}"></i></div><span class="value">${E(display)}</span></div>`).join('');
